        let messages: Vec<String> = r.check(&Catalog::new()).into_iter().map(|p| p.message).collect();
        assert_eq!(messages, vec!["`rating` has no operator `contains`".to_string(), "unknown field `nope`".to_string()]);
        let r = rs(
