    fn album_rule_ids() {
        use crate::{Album, AlbumId, Op};
        assert_eq!(album_rule_id(&json!(3)), Some(AlbumId(3)));
        assert_eq!(album_rule_id(&json!("3")), Some(AlbumId(3)));
        assert_eq!(album_rule_id(&json!(3.0)), Some(AlbumId(3)));
